import 'package:cephalopod/features/about/presentation/models/app_version_ui.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'about_view_state.freezed.dart';

/// Everything the About page shows: the address of the official rule sheet,
/// the app's [version] once it is known, and whether the last try to open
/// the rule sheet failed ([linkFailed]).
///
/// A UI model (docs/adr/0015): plain data generated by freezed
/// (docs/adr/0011).
@freezed
abstract class AboutViewState with _$AboutViewState {
  const factory AboutViewState({
    required String ruleSheetAddress,
    AppVersionUi? version,
    @Default(false) bool linkFailed,
  }) = _AboutViewState;
}
